// === Tab: mySketch ===
const size = 600;
const pad = 50;
const fillOptions = ["hachure", "cross-hatch", "dashed"];
const colorOptions = [
  { bg: "#efe7d8", color: "#111" },
  { bg: "#111", color: "#eee" },
];

let rc, horizon;

function setup() {
  const canvas = createCanvas(size, size);
  rc = rough.canvas(canvas.canvas);
  horizon = [pt(pad, height / 2), pt(width - pad, height / 2)];
  noLoop();
}

function draw() {
  const boxCount = int(random(3, 15));
  const sideInfo = { idx: int(random(0, 3)), style: random(fillOptions) };
  const { bg, color } = random(colorOptions);
  const pencilStyle = { roughness: 1.5, stroke: color, strokeWidth: 0.4 };

  background(bg);

  const boxes = [];
  let _wG_1 = 0; while ((boxes.length < boxCount) && ++_wG_1 < 20000) {
    const candidate = getBox();
    if (collides(candidate, boxes)) continue;
    boxes.push(candidate);
  }

  // draw horizon
  for (const point of horizon) drawCircle(point, 4, { fill: color });
  drawLine(horizon, pencilStyle);

  // draw boxes (just guide lines on first pass)
  for (const { guides } of boxes) {
    for (const line of guides) drawLine(line, pencilStyle);
  }

  // a second pass so that box lines and sides are above guide lines
  for (const { lines, sides } of boxes) {
    for (const side of sides) {
      drawPoly(side, { fill: bg, fillStyle: "solid" });
    }

    const { idx, style: fillStyle } = sideInfo;
    const side = sides[idx];
    if (side != null) {
      drawPoly(side, { fill: color, fillStyle, hachureAngle: idx > 1 ? 0 : 45 });
    }

    for (const line of lines) {
      drawLine(line, { roughness: 0.5, stroke: color, strokeWidth: 3 });
    }
  }

  // draw noise
  const count = width * 2;
  for (let i = 0; i < count; i++) {
    drawCircle(pt(random() * width, random() * height), random(0, 1), { fill: bg });
  }
}

function getBox() {
  const [lines, sides, guides] = [[], [], []];
  const [hl, hr] = horizon;

  // middle vertical line
  const mt = pt(random(pad + 100, width - pad - 100), random(pad, height - pad - 100));
  const mb = pt(mt.x, mt.y + random(30, 100));
  guides.push([mt, mb], [mt, hl], [mt, hr], [mb, hl], [mb, hr]);
  lines.push([mt, mb]);

  // left vertical line
  const lx = mt.x - random(15, 60);
  const lt = intersect([pt(lx, 0), pt(lx, height)], [mt, hl]);
  const lb = intersect([pt(lx, 0), pt(lx, height)], [mb, hl]);
  guides.push([lt, lb]);
  lines.push([lt, lb], [lt, mt], [lb, mb]);
  sides.push([
    [mt, mb],
    [mb, lb],
    [lb, lt],
    [lt, mt],
  ]);

  // right vertical line
  const rx = mt.x + random(15, 60);
  const rt = intersect([pt(rx, 0), pt(rx, height)], [mt, hr]);
  const rb = intersect([pt(rx, 0), pt(rx, height)], [mb, hr]);
  guides.push([rt, rb]);
  lines.push([rt, rb], [rt, mt], [rb, mb]);
  sides.push([
    [mt, mb],
    [mb, rb],
    [rb, rt],
    [rt, mt],
  ]);

  // below horizon
  if (mt.y > hl.y) {
    const meet = intersect([lt, hr], [rt, hl]);
    guides.push([lt, hr], [rt, hl]);
    lines.push([lt, meet], [rt, meet]);
    sides.push([
      [mt, lt],
      [lt, meet],
      [meet, rt],
      [rt, mt],
    ]);
  }

  // above horizon
  if (mb.y < hl.y) {
    const meet = intersect([lb, hr], [rb, hl]);
    guides.push([lb, hr], [rb, hl]);
    lines.push([lb, meet], [rb, meet]);
    sides.push([
      [mb, lb],
      [lb, meet],
      [meet, rb],
      [rb, mb],
    ]);
  }

  return { lines, sides, guides };
}

function drawCircle(point, diam, opts = {}) {
  rc.circle(point.x, point.y, diam, {
    stroke: "none",
    fillStyle: "solid",
    ...opts,
  });
}

function drawLine(line, opts = {}) {
  const [p1, p2] = line;
  rc.line(p1.x, p1.y, p2.x, p2.y, {
    disableMultiStroke: true,
    ...opts,
  });
}

function drawPoly(poly, opts = {}) {
  const points = poly.flatMap((line) => line).map((point) => [point.x, point.y]);
  rc.polygon(points, {
    roughness: 0.5,
    fillWeight: 1,
    hachureGap: 4,
    stroke: "none",
    ...opts,
  });
}

function pt(x, y) {
  return createVector(x, y);
}

function collides(candidateBox, existingBoxes) {
  const existingLines = existingBoxes.flatMap((b) => b.lines);

  for (const liA of candidateBox.lines) {
    if (existingLines.some((liB) => intersect(liA, liB) != null)) return true;
  }

  return false;
}

function intersect(lineA, lineB) {
  const [[p1, p2], [p3, p4]] = [lineA, lineB];
  const d = (p4.y - p3.y) * (p2.x - p1.x) - (p4.x - p3.x) * (p2.y - p1.y);
  if (d === 0) return;

  const ua = ((p4.x - p3.x) * (p1.y - p3.y) - (p4.y - p3.y) * (p1.x - p3.x)) / d;
  const ub = ((p2.x - p1.x) * (p1.y - p3.y) - (p2.y - p1.y) * (p1.x - p3.x)) / d;
  if (ua < 0 || ua > 1 || ub < 0 || ub > 1) return;

  const x = p1.x + ua * (p2.x - p1.x);
  const y = p1.y + ua * (p2.y - p1.y);
  return pt(x, y);
}


// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
if (typeof window.clm === 'undefined') {
